package main

import (
	"context"
	"fmt"
	"time"
)

// slowOp simulates work that takes 2 seconds, reporting back on a channel.
func slowOp() <-chan string {
	done := make(chan string, 1) // buffered so the goroutine never leaks
	go func() {
		time.Sleep(2 * time.Second)
		done <- "result"
	}()
	return done
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel() // release resources / stop the timer

	select {
	case res := <-slowOp():
		fmt.Println("got:", res)
	case <-ctx.Done(): // fires after 100ms
		fmt.Println("timed out:", ctx.Err())
	}
}

