package solution

import (
	"context"
	"time"
)

func DoWork(ctx context.Context, d time.Duration) (string, error) {
	result := make(chan string, 1) // buffered: send succeeds even if we already returned
	go func() {
		time.Sleep(d)        // simulate the work
		result <- "done"     // never blocks thanks to the buffer -> no leak
	}()

	select {
	case r := <-result:
		return r, nil // work won the race
	case <-ctx.Done():
		return "", ctx.Err() // cancelled or timed out first
	}
}

