func fetch(ctx context.Context) (string, error) {
	result := make(chan string, 1) // BUFFERED: send never blocks
	go func() {
		time.Sleep(2 * time.Second)
		result <- "data" // succeeds into the buffer even if we already returned
	}()
	select {
	case r := <-result:
		return r, nil
	case <-ctx.Done():
		return "", ctx.Err() // goroutine can still complete & exit -> no leak
	}
}

func WaitFirst(ctx context.Context, ch <-chan int) (int, error) {
	select {
	case v := <-ch: // a value arrived first
		return v, nil
	case <-ctx.Done(): // cancelled/timed out first
		return 0, ctx.Err()
	}
}
